import unicodedata
import re
import gettext

def normalize_lookup(text: str) -> str:
    if not text:
        return ""
    nfkd = unicodedata.normalize("NFD", text.strip())
    return "".join(c for c in nfkd if unicodedata.category(c) != "Mn").lower()

